/** Copy fixes, applied to every string of a project (description, sections, alt text). */
const TEXT_FIXES: [RegExp, string][] = [
  [
    /green for the tea-forward flavor, orange for the achari cashews, and so on down the line/g,
    'peach for the coffee almonds, green for the achaari cashews, red for the Thai sweet chilli peanuts, and so on down the line',
  ],
  [/while working the Graphē/g, 'while working at The Graphē'],
  [/Bengal Pro T20 League/g, 'Bengal T20 League'],
];
export const fixText = (s: string) => TEXT_FIXES.reduce((acc, [re, to]) => acc.replace(re, to), s);

