/** Applies every correction to a project after the import overlay. */
export function correct(w: Work): Work {
  const slug = w.slug;
  return {
    ...w,
    title: fixText(w.title),
    description: w.description?.map(fixText),
    sections: w.sections?.map((s) => ({ heading: s.heading, body: s.body.map(fixText) })),
    disciplines: DISCIPLINES[slug] ?? w.disciplines,
    clientType: CLIENT_TYPE[slug] ?? w.clientType,
    year: YEAR[slug] ?? w.year,
    links: LINKS[slug] ? [LINKS[slug]] : [],
    live: undefined,
    uvNotes: UV_NOTES[slug] ?? [],
    deliverables: w.deliverables.map((d) => ({ ...d, alt: fixText(d.alt) })),
  };
}
